for m in sorted(sys.modules.keys()):
    if 'sat' in m.lower() or 'sat' in m:
        print(f"  {m}")

edges = [(0, 1), (0, 7), (0, 8), (0, 13), (1, 4), (2, 7), (2, 8), (2, 12), (3, 10), (3, 12), (3, 13), (4, 5), (5, 6), (6, 9), (9, 11), (9, 14), (10, 11), (10, 14)]

# Verify all fixed edges
fixed_edges = [(2,12), (3,10), (6,9), (3,13), (3,12), (0,13)]
for e in fixed_edges:
    assert e in edges or (e[1], e[0]) in edges, f"Missing fixed edge {e}"
print("All fixed edges present!")

# Build adjacency
n = 15
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
deg = [len(adj[v]) for v in range(n)]
print(f"Degrees: {deg}")
assert all(2 <= d <= 5 for d in deg), "Degree constraint violated!"
print("All degrees in [2,5]!")

# Check girth using BFS from each vertex
from collections import deque

min_cycle = n+1
for s in range(n):
    dist = [-1]*n
    parent = [-1]*n
    dist[s] = 0
    q = deque([s])
    while q:
        v = q.popleft()
        for u in adj[v]:
            if dist[u] == -1:
                dist[u] = dist[v] + 1
                parent[u] = v
                q.append(u)
            elif u != parent[v]:
                # Found a cycle
                cycle_len = dist[v] + dist[u] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len

print(f"Girth: {min_cycle}")
assert min_cycle >= 4, f"Girth too small: {min_cycle}"
print("Girth >= 4 satisfied!")

# Let's also find all cycles of length 3 or 4 to be thorough
# Check for 3-cycles (triangles)
triangles = []
for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k in adj[i]:
                    triangles.append((i,j,k))
print(f"Triangles: {triangles}")

# Check for 4-cycles
four_cycles = []
for i in range(n):
    for j in adj[i]:
        if j > i:
            for k in adj[j]:
                if k > j and k != i:
                    for l in adj[k]:
                        if l > k and l != j and l in adj[i] and l != j:
                            four_cycles.append((i,j,k,l))
print(f"4-cycles: {four_cycles}")

print("\nGraph is valid!")
